                        vfloat32m8_t _w = __riscv_vle32_v_f32m8(kptr, vl);
                        vfloat32m8_t _sval = __riscv_vfmv_v_f_f32m8(sval, vl);
                        // sum += w * sval
                        _sum = __riscv_vfmacc_vv_f32m8(_sum, _w, _sval, vl);
                        kptr += packn;
                    }
