        if (ret != 0)
            return ret;
        return 0;
    }
#endif

    return convolution_scalar(bottom_blob_bordered, top_blob, weight_data, bias_data, kernel_w, kernel_h, stride_w, stride_h, dilation_w, dilation_h, activation_type, activation_params, opt);
}

