   146	                    const float* sptr = m.row(i * stride_h) + j * stride_w;
   147	
   148	                    for (int k = 0; k < maxk; k++)
   149	                    {
   150	                        float sval = sptr[space_ofs[k]];
   151	                        vfloat32m8_t _w = __riscv_vle32_v_f32m8(kptr, vl);
   152	                        vfloat32m8_t _sval = __riscv_vfmv_v_f_f32m8(sval, vl);
   153	                        // sum += w * sval
   154	                        _sum = __riscv_vfmacc_vv_f32m8(_sum, _w, _sval, vl);
   155	                        kptr += packn;
   156	                    }
   157	                }
   158	
   159	                // activation
   160	                // activation_ss(sum) per lane
   161	                float* outp = outptr + j * packn;
   162	                // store vector then apply scalar activation per element to avoid non-portable masked funcs
   163	                float tmpbuf[64];
   164	                __riscv_vse32_v_f32m8(tmpbuf, _sum, vl);
   165	                for (size_t t = 0; t < vl; t++)
   166	                {
   167	                    outp[t] = activation_ss(tmpbuf[t], activation_type, activation_params);
   168	                }
   169	            }
   170	            outptr += outw * packn;
   171	        }
   172	    }
   173	
   174	    // tail output channels
   175	    for (; p < outch; p++)
   176	    {
   177	        float* outptr = top_blob.channel(p);
   178	        for (int i = 0; i < outh; i++)
   179	        {
   180	            for (int j = 0; j < outw; j++)
   181	            {
   182	                float sum = bias_term ? bias_data[p] : 0.f;
   183	                const float* kptr = (const float*)weight_data + maxk * inch * p;
   184	                for (int q = 0; q < inch; q++)
   185	                {
   186	                    const Mat m = bottom_blob.channel(q);
   187	                    const float* sptr = m.row(i * stride_h) + j * stride_w;
   188	                    for (int k = 0; k < maxk; k++)
   189	                    {
   190	                        sum += sptr[space_ofs[k]] * kptr[k];
   191	                    }
   192	                    kptr += maxk;
   193	                }
   194	                outptr[j] = activation_ss(sum, activation_type, activation_params);
   195	            }
   196	            outptr += outw;
   197	        }
   198	    }
   199	
   200	    return 0;
   201	}
   202	#endif // __riscv_vector
