    80	static void convolution_transform_kernel_packed_sse(const Mat& weight_data, Mat& weight_data_tm, int num_input, int num_output, int kernel_w, int kernel_h, int elempack, int out_elempack)
    81	{
    82	    const int maxk = kernel_w * kernel_h;
    83	
    84	    // src = kw-kh-inch-outch
    85	    // dst = pb-pa-kw-kh-inch/pa-outch/pb
    86	    {
    87	        Mat weight_data_r2 = weight_data.reshape(maxk, num_input, num_output);
    88	
    89	        weight_data_tm.create(maxk, num_input / elempack, num_output / out_elempack, (size_t)4u * elempack * out_elempack, elempack * out_elempack);
    90	
    91	        for (int q = 0; q + (out_elempack - 1) < num_output; q += out_elempack)
    92	        {
    93	            float* g00 = weight_data_tm.channel(q / out_elempack);
    94	
    95	            for (int p = 0; p + (elempack - 1) < num_input; p += elempack)
    96	            {
    97	                for (int k = 0; k < maxk; k++)
    98	                {
    99	                    for (int i = 0; i < elempack; i++)
   100	                    {
   101	                        for (int j = 0; j < out_elempack; j++)
   102	                        {
   103	                            const float* k00 = weight_data_r2.channel(q + j).row(p + i);
   104	
   105	                            g00[0] = k00[k];
   106	
   107	                            g00++;
   108	                        }
   109	                    }
   110	                }
   111	            }
   112	        }
   113	    }
