   124	static int convolution(const Mat& bottom_blob, Mat& top_blob, const Mat& weight_data, const Mat& bias_data, int kernel_w, int kernel_h, int stride_w, int stride_h, int dilation_w, int dilation_h, int activation_type, const Mat& activation_params, const Option& opt)
   125	{
   126	    const int w = bottom_blob.w;
   127	    const int inch = bottom_blob.c;
   128	
   129	    const int outw = top_blob.w;
   130	    const int outh = top_blob.h;
   131	    const int outch = top_blob.c;
   132	
   133	    const int bias_term = bias_data.empty() ? 0 : 1;
   134	
   135	    const int maxk = kernel_w * kernel_h;
   136	
   137	    // kernel offsets
   138	    std::vector<int> _space_ofs(maxk);
   139	    int* space_ofs = &_space_ofs[0];
   140	    {
   141	        int p1 = 0;
   142	        int p2 = 0;
   143	        int gap = w * dilation_h - kernel_w * dilation_w;
   144	        for (int i = 0; i < kernel_h; i++)
   145	        {
   146	            for (int j = 0; j < kernel_w; j++)
   147	            {
   148	                space_ofs[p1] = p2;
   149	                p1++;
   150	                p2 += dilation_w;
   151	            }
   152	            p2 += gap;
   153	        }
   154	    }
   155	
   156	    #pragma omp parallel for num_threads(opt.num_threads)
   157	    for (int p = 0; p < outch; p++)
   158	    {
   159	        float* outptr = top_blob.channel(p);
   160	
   161	        for (int i = 0; i < outh; i++)
   162	        {
   163	            for (int j = 0; j < outw; j++)
   164	            {
   165	                float sum = 0.f;
   166	
   167	                if (bias_term)
   168	                    sum = bias_data[p];
   169	
   170	                const float* kptr = (const float*)weight_data + maxk * inch * p;
   171	
   172	                for (int q = 0; q < inch; q++)
